MATCH (m:Movie)-[:receivesAward]->(a:Award)
WHERE EXISTS {
  MATCH (m)-[:receivesAward]->(ja:Award {name: "Jameson People's Choice Award for Best Actor"})
}
RETURN a.name, count(DISTINCT m) AS movie_count

MATCH (m:Movie)-[:directedBy]->(p:Person)
WHERE p.date_of_death = date("2006-11-20")
  AND EXISTS {
    MATCH (m)-[:releasedIn]->(c:Country {name: "Canada"})
  }
RETURN DISTINCT p.name
